WITH Src AS (SELECT *, CONCAT_WS('-', location, dept_name) AS location_dept_name_key FROM departments WHERE dept_name <> 'Marketing'), summary AS (SELECT dept_name, AVG(budget) AS avg_budget, SUM(CASE WHEN location = 'Berlin' THEN 1 ELSE 0 END) AS berlin_count FROM Src GROUP BY dept_name) SELECT dept_name, avg_budget, berlin_count FROM summary WHERE berlin_count > 37 ORDER BY avg_budget DESC
